campaignTrail_temp.answer_feedback_json = [
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41786,
        "fields": {
            "answer": 41782,
            "candidate": 300,
            "answer_feedback": "This type of messaging IS what the American people want, but it’s a little weird and seems off coming from a hedge fund manager like you."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41787,
        "fields": {
            "answer": 41783,
            "candidate": 300,
            "answer_feedback": "Your record says you’re a fighter, but your personality says otherwise. People appreciate that you’re willing to be a bit aggressive, but you just come off a bit like a dork for trying."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41788,
        "fields": {
            "answer": 41784,
            "candidate": 300,
            "answer_feedback": "Climate change isn’t really on anybody’s radar this year, although I guess it’s a winning message if you want to get Green Party support."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41789,
        "fields": {
            "answer": 41785,
            "candidate": 300,
            "answer_feedback": "This works surprisingly well. Some people might say you’re TOO rich to actually know about working-class issues, but a focus on the economy never hurt anyone."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41801,
        "fields": {
            "answer": 41800,
            "candidate": 300,
            "answer_feedback": "This works just as planned. You get massive wins in Virginia and Alabama to strengthen your lead and you become the presumptive nominee soon enough."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41810,
        "fields": {
            "answer": 41809,
            "candidate": 300,
            "answer_feedback": "This works like a charm. Bloomberg’s campaign falters as he loses in Texas, and Sanders’ momentum also slows down with a loss in California. By building up large delegate totals, you separate yourself from the rest of the pack."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41815,
        "fields": {
            "answer": 41814,
            "candidate": 300,
            "answer_feedback": "You don’t win either states, but you do well enough to eventually force Buttigieg and Warren out of the race. Voters in those states also appreciate the attention you’re giving them."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41827,
        "fields": {
            "answer": 41826,
            "candidate": 300,
            "answer_feedback": "This is an interesting strategy, but it works surprisingly well. You do win those smaller states by pretty sizable margins, and the people actually become convinced that you’re the overwhelming frontrunner just based on the number of states you win."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41847,
        "fields": {
            "answer": 41846,
            "candidate": 300,
            "answer_feedback": "This kind of works. You spend a bit of time getting some advice on public image and speaking skills to rebrand your image as someone more dynamic. Ironically, your tartan tie ends up becoming an iconic symbol for your “good vibes” campaign."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41853,
        "fields": {
            "answer": 41852,
            "candidate": 300,
            "answer_feedback": "Some people don’t like the negative tone of your attacks and point out that this is basically all you did in the primaries, but hey, if it ain't broke don't fix it right?\" "
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41858,
        "fields": {
            "answer": 41857,
            "candidate": 300,
            "answer_feedback": "You hit the trail with a rotating cast of opponents every few days. de Blasio, Buttigieg, and Warren one week; Biden, Booker, and O’Rourke the next, and so on. Their old supporters slowly begin to warm up to you more as you pal around with their favorite candidates, although you make a point to avoid Williamson and don’t even call Gravel."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41870,
        "fields": {
            "answer": 41869,
            "candidate": 300,
            "answer_feedback": "Progressives already distrusting of your liberal bona fides are becoming more and more discouraged into not voting, but I’m sure this gamble with “Never Trumpers” will pay off… right?"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41879,
        "fields": {
            "answer": 41877,
            "candidate": 300,
            "answer_feedback": "Oh Tom, you're about to choke on those words. Bernie is clearly angry, and Warren even takes her time to approach you and chew you out for what she deems as “Just a really dumb campaign strategy.” At least the RINOs like you a bit more."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41886,
        "fields": {
            "answer": 41881,
            "candidate": 300,
            "answer_feedback": "This goes over pretty well. Phil’s conciliatory personality plays well and he does sound genuinely proud of working with Vermont Democrats to get things done. While he didn’t exactly enthuse the base, he’s helping you keep the coalition together for now."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41889,
        "fields": {
            "answer": 41888,
            "candidate": 300,
            "answer_feedback": "Even Pressley’s strongest critics must admit she’s a strong speaker, but her rattling off about healthcare reform and the Green New Deal has substantially spooked some of the moderates you won over by picking Phil, not to mention some of what she said directly opposes the policies you support. Bernie seems at least happy."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41895,
        "fields": {
            "answer": 41894,
            "candidate": 300,
            "answer_feedback": "Weld is a good man who’s respected by everyone across the spectrum, and his speech goes over actually quite well. But this tanks so much progressive support you were able to hold on to after Reich’s departure, and Bernie privately tells you he wishes you had picked someone else."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41901,
        "fields": {
            "answer": 41900,
            "candidate": 300,
            "answer_feedback": "Gretchen Whitmer gets the blood pumping. She’s young, energetic, attractive, and people have a lot of trust in her, and you might’ve even picked her as VP if she didn’t decline to keep governing. She could probably be a senator someday… maybe something higher. "
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41913,
        "fields": {
            "answer": 41906,
            "candidate": 300,
            "answer_feedback": "Jimmy Carter’s old, of course, but who’s going to complain about one of the world’s greatest humanitarians giving a speech? Joined by his wife Rosalynn, Jimmy gives a heartwarming speech about the strength of good and how you’ve worked hard for that. You feel like the two of you share a certain kinship."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41917,
        "fields": {
            "answer": 41916,
            "candidate": 300,
            "answer_feedback": "Your blood seemed to boil as more and more words blasted out of your mouth. Everyone, from the center to the left is roaring, you got their blood pumping. In retrospect, did you really say anything new? No. But for that single moment, America and its rage is behind you for once. "
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41921,
        "fields": {
            "answer": 41920,
            "candidate": 300,
            "answer_feedback": "Well… the message itself wasn’t bad. But the delivery certainly left a lot to be desired. One commentator says he’s seen more exciting speeches from Chris Dodd, and you have to dig through Google to figure out who the hell they’re even referring to. The speech was generally decently received though, just don’t expect major convention bumps."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41924,
        "fields": {
            "answer": 41923,
            "candidate": 300,
            "answer_feedback": "Your overall message of reforming Washington is great… or at least it would’ve been in 2016 against Trump. People still like the overall populist spin of it, although they don’t seem to quite fully buy the last part about the corporations given your hedge fund past."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41932,
        "fields": {
            "answer": 41928,
            "candidate": 300,
            "answer_feedback": "I guess you’re right, but stressing that you are an outsider this much is getting a bit tiring, and after the last four years, your vague answer of being another outsider aren’t reassuring ANYONE."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41933,
        "fields": {
            "answer": 41931,
            "candidate": 300,
            "answer_feedback": "Giving the American people some idea of what your Cabinet will look like is certainly reassuring as you assemble your “dream team”. The GOP will always treat even the most qualified Democrats as the Legion of Doom."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41937,
        "fields": {
            "answer": 41936,
            "candidate": 300,
            "answer_feedback": "This kind of works. The policy wonk image you created at least reassures the people that you’re ready for the job, but you get so overexplanatory on some answers that you put people to sleep. "
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41942,
        "fields": {
            "answer": 41941,
            "candidate": 300,
            "answer_feedback": "The base loves it, especially the ever present wine moms. Trump is making a big stink about it though, and some say impeachment is a dead issue. Maybe you should start selling bumper stickers that say “LOCK HIM UP!”. That’ll really get under his skin."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41950,
        "fields": {
            "answer": 41949,
            "candidate": 300,
            "answer_feedback": "Those who supported you from the start specifically on impeachment feel pretty betrayed, although you’re right that impeachment isn’t really a major issue anymore. Still, those poor, poor wine moms."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41953,
        "fields": {
            "answer": 41952,
            "candidate": 300,
            "answer_feedback": "Most Americans rely on Obamacare, whether they want to admit it or not, and your promise to expand it has been a Democratic rallying cry for years. The only people who don’t “trust the science” might not live until election day anyway."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41956,
        "fields": {
            "answer": 41955,
            "candidate": 300,
            "answer_feedback": "This policy isn’t actually that unreasonable and small business owners certainly appreciate it, but you can hear an audible groan from the left when you remind them that you’re a businessman yet once again."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41960,
        "fields": {
            "answer": 41959,
            "candidate": 300,
            "answer_feedback": "Trump calls you a raging socialist, Republicans (and frankly most people) are calling you a flip-flopper. Phil isn’t happy with you at all. Bernie, however, says someone finally knocked some sense into you. On the whole though, the general public is pretty confused about this about-turn."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41968,
        "fields": {
            "answer": 41967,
            "candidate": 300,
            "answer_feedback": "Clyburn chews you out from behind closed doors on how he expected better from someone he trusted, but agrees to take the lead on this with Obama and others as you agree to support them. The black crowds you speak to are notably more deflated than before, though."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41982,
        "fields": {
            "answer": 41981,
            "candidate": 300,
            "answer_feedback": "It’s obvious that framing yourself around this movement but in a more reasonable way won’t only be a good strategy but a winning one. Offering actual policy further extends that olive branch and reassures moderates too. The hardcore activists will always be disappointed, but you can’t win them all."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41987,
        "fields": {
            "answer": 41986,
            "candidate": 300,
            "answer_feedback": "This speech actually goes over quite well and people are genuinely heartened by your obvious empathy at play here. Reverend Jesse Jackson even gives you a call and says he’s glad he endorsed you, although he hopes to see more concrete policy on this in the future."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 41991,
        "fields": {
            "answer": 41990,
            "candidate": 300,
            "answer_feedback": "No one technically disagrees with this anti-violence message given that no one but the most extreme left likes these riots, but people note your hesitation to actually address the issue of police violence in any meaningful way and think you’ve just sided with Trump."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42010,
        "fields": {
            "answer": 42006,
            "candidate": 300,
            "answer_feedback": "This seems like a nice compromise to most people, but they ARE hesitant about letting private corporations be involved with this stuff, even in a limited capacity. The only people who aren’t usually are Republicans, but anything with the name ‘Green New Deal’ in it is too much."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42013,
        "fields": {
            "answer": 42007,
            "candidate": 300,
            "answer_feedback": "Nothing explosive given this is basically what people expect from the average Democratic candidate. Most people who supported you had been hoping that you might’ve put a little more focus on this given how much you focused on it in the primaries, though. "
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42016,
        "fields": {
            "answer": 42008,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>Despite Phil begging you not to take such a ‘radical’ stance, siding with the Green New Deal actually gets progressives to take interest in your campaign. Some moderates feel like you’re alienating them, but given they at least agree that climate change is important, they’ll still vote for you to stop Trump for the most part. On top of this many people are actually reading the GND policies, and find themselves agreeing with parts of it. Bernie even publicly says you’re “finally making some damn sense”.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42023,
        "fields": {
            "answer": 42022,
            "candidate": 300,
            "answer_feedback": "Maximizing trade is good and all, but some folks in the Midwest are still nervous that even more of their jobs will go overseas. And y’know, maximizing trade doesn't prevent wars so your foreign policy credentials are still in question."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42027,
        "fields": {
            "answer": 42025,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>You take a quick trip across key countries, meeting with Tony Blair, David Cameron, Brian Mulroney, Vincente Fox, Kevin Rudd, Malcolm Trumbull, and Donald Tusk among others, finding a surprisingly close connection to the outgoing Governor of the Bank of England, who you think would make a great partner on the world stage. Compared to the clear annoyance they showed with Trump, you actually look like a respected equal next to them.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42029,
        "fields": {
            "answer": 42026,
            "candidate": 300,
            "answer_feedback": "Those neocons were probably going to vote for Trump anyway. If there’s anything moderates, liberals and progressives can broadly agree on is that the US is too involved in global military affairs."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42033,
        "fields": {
            "answer": 42032,
            "candidate": 300,
            "answer_feedback": "This works well enough, but the usual suspects are calling your suggestions for further restrictions if necessary as “unfettered fascism”. Still, no one’s against ending the pandemic faster."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42035,
        "fields": {
            "answer": 42034,
            "candidate": 300,
            "answer_feedback": "The Republicans complain about “big government spending” as usual but it’s hard for them to complain too much when even Trump supports some version of a stimulus. Not like you were going to get them to vote for you anyway. "
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42039,
        "fields": {
            "answer": 42038,
            "candidate": 300,
            "answer_feedback": "Everyone likes tax cuts, although there’s a bit of ridicule that goes your way that always pops up when you say something anti-billionaire. "
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42043,
        "fields": {
            "answer": 42042,
            "candidate": 300,
            "answer_feedback": "Nobody hates infrastructure spending, and Biden’s pretty happy to see you embrace it. Let’s hope you’ve got the Congressional makeup to push this through, though."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42047,
        "fields": {
            "answer": 42046,
            "candidate": 300,
            "answer_feedback": "Mother of God, Tom. The liberals and progressives are eating this up, but just as the great FDR himself was accused of, people are calling you an authoritarian. Phil is furious that you would even suggest this. Was this really a good choice?"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42053,
        "fields": {
            "answer": 42052,
            "candidate": 300,
            "answer_feedback": "Fair enough. Breyer is almost sure to retire during the next Democratic presidency, while Sotomayor might be tougher to convince. This doesn’t make waves either way."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42055,
        "fields": {
            "answer": 42054,
            "candidate": 300,
            "answer_feedback": "You are immediately met with intense criticism for “trying to undermine the integrity of our justices”, and John Roberts even has some sharp words to say about the politicization of the courts, but the justices doth protest too much, methinks, and it’s not like it’s a bad idea to make sure judges aren’t engaging in ethical violations."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42064,
        "fields": {
            "answer": 42060,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>You’ve obviously got Pete by your side as you campaign through some of the areas that Obama had done well in 2008. The Bayh family comes out of political retirement to give you a hand too. The one thing that you keep remembering though is a strange encounter with Republican congressional candidate Victoria Spartz who says she likes you “despite your socialism” because she feels kinship with you for some reason.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42067,
        "fields": {
            "answer": 42061,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>Unexpectedly through your tour through the state, you end up running into Bob Dole. You fear being like him, another forgotten candidate sent to the meat grinder of history. The two of you share a surprisingly warm moment despite his ardent support for Trump. Later that day he calls you a “nice man”. Trump insults him on Twitter, calling him a fake hero. The insult is news for a day, before it’s cast into the wind.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42068,
        "fields": {
            "answer": 42062,
            "candidate": 300,
            "answer_feedback": "Initially, you had just planned on getting the Castro brothers and O’Rourke to campaign with you, but you were unexpectedly joined by a young, relatively unknown, freshman state representative named James Talarico. He impresses you far more than any of your other surrogates in the state, and you can tell he’s going to be big."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42070,
        "fields": {
            "answer": 42063,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>You manage to get Evan McMullin and Congressman Ben McAdams by your side as you rally in Salt Lake City, where the Mormons actually seem pretty receptive to your campaign. Afterwards, you’re greeted with a surprise appearance from Romney himself, who whispers in your ear that you’ve got his vote. As he gives you a handshake, you hear the voice of another New Englander coming from nowhere, this one long dead: “Tom, you must stop him, for me, for us.” You weirdly feel the urge to travel to Carthage, Illinois. afterwards.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42095,
        "fields": {
            "answer": 42092,
            "candidate": 300,
            "answer_feedback": "Well… everyone agreed that the debates were a disaster. Neither of you came off as presidential, but most voters polled actually seemed to like some of your attacks on Trump. The one that got clipped the most was when you smirked and said “the only number you measure bigger than me is the number of bankruptcies”. "
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42101,
        "fields": {
            "answer": 42093,
            "candidate": 300,
            "answer_feedback": "Yeah… this doesn’t work too well. People overall did say that they liked you more on a personal level, but you somehow came off as less presidential than Trump to them because you didn’t even hit back at Trump once. Maybe you should’ve told him to shut up at some point."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42104,
        "fields": {
            "answer": 42094,
            "candidate": 300,
            "answer_feedback": "In terms of “presidential”, you won by a lot. But this didn’t stop Trump from calling you “the biggest nerd in the world, even more than Dukakis”. And in the end, whatever voters you convinced to your side with policy, you lost the entire debate by your admittedly boring answers."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42109,
        "fields": {
            "answer": 42107,
            "candidate": 300,
            "answer_feedback": "The Republicans get enraged and call you “unpresidential” for taking advantage of Trump’s sickness (as if they’ve cared about unpresidential behavior for the last four years), but your surprisingly snarky comments about not hoping he injects bleach into his veins actually seem to make you MORE popular."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42112,
        "fields": {
            "answer": 42108,
            "candidate": 300,
            "answer_feedback": "This was about the answer the people expected. I guess there's no use attacking a sick man. The campaign goes on."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42116,
        "fields": {
            "answer": 42114,
            "candidate": 300,
            "answer_feedback": "Phil’s not really happy that he has to take this stance to begin with, but he obliges. Despite this, his clear discomfort with the leftward shift makes him contradict himself all over the place, making Pence seem like the principled conservative."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42120,
        "fields": {
            "answer": 42115,
            "candidate": 300,
            "answer_feedback": "This works like a charm. Phil effectively bridges the gap between moderates and progressive and really takes Pence to task, asking him how Pence can claim to be a Christian and still stand by the most morally corrupt President in history. Post-debate polls show an overwhelming victory for Phil."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42129,
        "fields": {
            "answer": 42125,
            "candidate": 300,
            "answer_feedback": "You can hear the cheering, despite the empty auditorium. It was grand, it was muffled, you felt like a savior, a hero of the people poised to rid the world of the plague known as Donald J. Trump. The next day however, you wake up with a nasty fever, your body aching all over, it feels like there’s nails in your throat. Trump, that bastard, gave you COVID."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42132,
        "fields": {
            "answer": 42126,
            "candidate": 300,
            "answer_feedback": "In a comedy of errors, Trump gets COVID for the second time, this time putting him out of commission for a while longer; you on the other hand, lose horrifically, at least that’s what you’re told by the post-debate polls. Most of the debate was Trump insulting you over and over again."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42135,
        "fields": {
            "answer": 42127,
            "candidate": 300,
            "answer_feedback": "Trump refuses to have a virtual debate, arguing that you’re going to rig it somehow virtually. The two of you end up holding duelling town halls at the same time. More people watched your town hall, you actually managed to come off quite folksy and personable while Trump argued with one of the audience members for some reason."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42140,
        "fields": {
            "answer": 42128,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>Platforming Reich was a bad move. While his unbelievably short height makes him the butt of the joke, he’s actually quite a formidable debater. He gets out far too many zingers and it throws you off your balance. Meanwhile you look over to the Libertarian candidate. Daniel Imperato spent nearly the entire debate rambling about nonsense, and oddly enough, people like him; between your squabbling with Reich, Imperato looks like the everyman. The average American. Eccentric sure, but he’s truly an American. The final straw poll has him beating you.<p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42954,
        "fields": {
            "answer": 42953,
            "candidate": 300,
            "answer_feedback": "This flooding doesn’t really work when most of the people criticizing you are doing it online or in-person. You trying to dodge it made even the least terminally online progressives and leftists not want much to do with you."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42957,
        "fields": {
            "answer": 42956,
            "candidate": 300,
            "answer_feedback": "This bodes the best with the progressives. The “online” leftists completely abandoned you a while ago, but the more reasonable ones take it pretty well, given how rare it is for a presidential candidate to outright admit that they were wrong, and your work on the environment certainly proves you’re a changed man."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42963,
        "fields": {
            "answer": 42959,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>Warren and others reluctantly agree, if only for the sake of the party. They do talk to the crowd about how great they think you are, but you can tell that their heart’s not in it. Afterwards, both of them are essentially crucified by the online left for being a traitor to the progressive cause, and Bernie even comes out to talk about how ‘embarrassing’ it was for Warren; she now doesn’t even return your calls for further campaigning, and word is that she is telling people to vote for Reich.<p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42966,
        "fields": {
            "answer": 42965,
            "candidate": 300,
            "answer_feedback": "This isn’t the worst idea, given that most voters will just take Trump’s ramblings as the idiotic lunacy they are, but some people are worried that you’re letting this stuff just go by without even bothering to counter it a little."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42971,
        "fields": {
            "answer": 42970,
            "candidate": 300,
            "answer_feedback": "You’ve said this so much it feels like no one will listen to you. The only people who seem to believe this are the liberals and the progressives. No one actually thinks Trump would try to overthrow the government, right? Right?"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42977,
        "fields": {
            "answer": 42973,
            "candidate": 300,
            "answer_feedback": "The clip of you calling Trump a loser is all over the news and it causes him to go on an extremely disturbing (even by Trump stands) profanity-laden, accusing you of being a “homosexual communist Chinese asset who hates this country more than Obama ever did”. Even Ted Cruz crawls out to make a mild comment criticizing Trump."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42982,
        "fields": {
            "answer": 42981,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>You’ve been screaming this at every podium, into every microphone, in every auditorium that will take you. It’s exhausting. You know you’re right. Plenty of Americans know you’re right. A part of you just wants it over, no matter the outcome. You’ve let yourself become a politician. You’ve adapted and molded to whatever opposes Trump the most. Americans trust you, people all around the world trust you. You are truly the people's candidate.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42988,
        "fields": {
            "answer": 42985,
            "candidate": 300,
            "answer_feedback": "It’s hard to appeal to the 99% when you’re part of the 1%. Unity is a message that would’ve worked in 2008, or 2012. And maybe it would’ve worked if you had a record of doing it like Biden. But now, it’s obvious that the only way to bring back unity is to cleanse this country of Donald Trump."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42989,
        "fields": {
            "answer": 42986,
            "candidate": 300,
            "answer_feedback": "Can you really deliver change? You hope you can. You know you want to make America a better country. You know you have the vision and the conviction for it. You believe in yourself. Now you wonder if the American people believe in you enough to carry you to the White House."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 42993,
        "fields": {
            "answer": 42992,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>You can tell there’s a bright future ahead for Senator Klobuchar, who even gets Walter Mondale to stump for you. She’s a fiery personality and you think she’ll be a valuable help… just not in your administration. This whistle-stop tour is exactly what everyone had been expecting you to do and you can tell Trump will never win any of these states again. You finish with your speech to a crowd of cheering supporters in Minneapolis, your running mate proudly by your side.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43000,
        "fields": {
            "answer": 42999,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>You wish you had Cooper’s easygoing charm as he fires up the crowd of the party’s old faithful, the African-American voters across the South, helping out Senate candidates like Doug Jones, Raphael Warnock, and Jon Osssoff… although you make a point to avoid Cunningham. You finish with your speech to a crowd of cheering supporters in Miami, your running mate proudly by your side.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43008,
        "fields": {
            "answer": 43007,
            "candidate": 300,
            "answer_feedback": "Kamala is definitely a fiery and strong speaker who you also happen to like. You’ve comparatively been weaker in these states than in others, but you can tell they’re slowly becoming more and more supportive of you. You finish with your speech to a crowd of cheering supporters in San Francisco, your running mate proudly by your side."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43018,
        "fields": {
            "answer": 43016,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>Had the governor not been a Republican, you know Brown would be your running mate, but I guess him campaigning by you is the second best thing. The two of you are joined by a variety of other Pennsylvania & Ohio stars as you fight for two of the biggest swing states in the Union. You finish with your speech to a crowd of cheering supporters in Cleveland, your running mate proudly by your side.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43047,
        "fields": {
            "answer": 43046,
            "candidate": 300,
            "answer_feedback": "Bernie and Phil’s weirdly profound respect for one another has left Bernie sitting this out. He won't endorse you, he won’t be campaigning for you or anything, but if you ever need any policy ideas. You can call him."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43067,
        "fields": {
            "answer": 43061,
            "candidate": 300,
            "answer_feedback": "You offered him a plate of nothing, and expected him to back you. He is living proof that a third party can hypothetically win elections. Bernie endorsed Reich, leaving the progressives in your own coalition disoriented and Leaving a huge hole in the bottom."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43112,
        "fields": {
            "answer": 43109,
            "candidate": 300,
            "answer_feedback": "Phil is notably frustrated that you’re willing to make such major concessions and move to the left. This still isn’t really enough to get Bernie to endorse you either, but he’s at least managed to convince most big-name politicians to abstain from endorsing Reich."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43141,
        "fields": {
            "answer": 43140,
            "candidate": 300,
            "answer_feedback": "Warren knows you aren’t going to be running around parrotting her rhetoric, but she nonetheless makes sure to emphasize how much she trusts your cause to appeal to progressives too. Although some Bernie Bros still haven’t completely forgiven Warren after the primaries, everyone is left happy."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43157,
        "fields": {
            "answer": 43155,
            "candidate": 300,
            "answer_feedback": "Arnie is a figure beloved both by the left and the right, and he looks absolutely presidential as he rumbles about what a disgrace to the country Trump is and how much he wishes for REAL leadership. He talks about how you can see MAGA bleed with the failures of Trump, and “If it bleeds, we can kill it.”"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43191,
        "fields": {
            "answer": 43189,
            "candidate": 300,
            "answer_feedback": "Interesting choice. Bullock is more than happy to campaign with you in Montana, and Tester accompanies you in some of the neighboring states. Your chances of actually winning them might not be extraordinarily high, but with good enough showings in them this time around, they might become competitive in the future."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43200,
        "fields": {
            "answer": 43189,
            "candidate": 300,
            "answer_feedback": "Enter feedback text here"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43202,
        "fields": {
            "answer": 43201,
            "candidate": 300,
            "answer_feedback": "You’re right about that. South Carolina isn’t competitive, obviously but the extra attention with Black voters in North Carolina, Georgia, and Florida is bound to do you good in November, and hopefully the increased turnout will help the key Senate races down in those states."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43237,
        "fields": {
            "answer": 43236,
            "candidate": 300,
            "answer_feedback": "Bernie pauses and just glares at you. He’s disgusted that you’d be willing to crumble so easily under pressure, and finding your groveling “pathetic”, publicly endorses Reich, saying “at least Bob Reich has a backbone. I can’t say the same about Steyer.”"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43257,
        "fields": {
            "answer": 43256,
            "candidate": 300,
            "answer_feedback": "It’s the next day, and your stomach and your heart hurts as you watch Meet the Press. Bernie tells Chuck Todd that you “aren’t the best choice” for president. It’s an anti-endorsement, a suggestion to “vote for anyone else but him.”"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43272,
        "fields": {
            "answer": 43271,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>Phil still has some commitment to the cause of beating Trump, he agrees. When news gets to the DNC though, they freak out. An emergency mico-convention is held through a Zoom call, and Maxine Waters is thrown onto the ticket with no one else willing to take the spot, and her residency is switched to DC despite the complications it brings with her re-election bid. You have no say in it at all.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43349,
        "fields": {
            "answer": 43348,
            "candidate": 300,
            "answer_feedback": "<div style='overflow-y:scroll;height:200px;'><p>Phil feels quite antagonized and outright announces that he will no longer be supporting your campaign, taking with him the endorsements of Kasich and Flake. When news gets to the DNC, they freak out. An emergency mico-convention is held through a Zoom call, and Maxine Waters is thrown onto the ticket with no one else willing to take the spot, and her residency is switched to DC despite the complications it brings with her re-election bid. You have no say in it at all.</p>"
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43435,
        "fields": {
            "answer": 43434,
            "candidate": 300,
            "answer_feedback": "Reich is actually pretty satisfied with this. He announces that he will be suspending his campaign “in the interest of defeating Trump”. Nina Turner will continue campaigning her grievance politics, but she’s but a fly on the wall now."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43440,
        "fields": {
            "answer": 43439,
            "candidate": 300,
            "answer_feedback": "Reich does appreciate you reaching out and willing to compromise a bit. He says he can’t possibly suspend the campaign now, but he does notably pull back the campaign in swing states."
        }
    },
    {
        "model": "campaign_trail.answer_feedback",
        "pk": 43452,
        "fields": {
            "answer": 43451,
            "candidate": 300,
            "answer_feedback": "You’re going to come to regret these words, aren’t you? Reich shows no signs of slowing down and he continues to eat into your numbers."
        }
    }
];

